mapper.select:
SELECT email, name, career_years, region, available_time, hourly_rate, intro, status, reg_time, mod_time
FROM tbl_babysitter_profile
WHERE email = #{email}

mapper.sql:
WHERE status = 'ACTIVE'

    AND region = #{search.region}


    AND career_years >= #{search.minCareerYears}


    AND (name LIKE CONCAT('%', #{search.keyword}, '%')
         OR intro LIKE CONCAT('%', #{search.keyword}, '%'))
